import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';

import { APP_VERSION } from '../pwa/app-info';
import credits from '../pwa/credits.json';
import { UpdateService } from '../pwa/update.service';
import { UI_ICONS } from '../ui/icons';

interface Credit {
  name: string;
  version?: string;
  license: string;
  url: string;
}

/** Libraries and assets shipped in the app bundle, generated by scripts/credits.mjs. */
const CREDITS: Credit[] = credits;

@Component({
  selector: 'rss-about',
  host: { class: 'block anim-fade-in' },
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <section class="panel">
      <h2 class="mb-1 text-base font-bold">RSS Reader</h2>
      <p class="text-sm text-muted">Version {{ version }}</p>
      <div class="mt-3 flex flex-wrap items-center gap-3">
        @if (updates.available()) {
          <button class="btn" type="button" (click)="updates.apply()">Installer la mise à jour</button>
        } @else {
          <button class="btn" type="button" [disabled]="checking()" (click)="check()">{{ checking() ? 'Recherche…' : 'Rechercher une mise à jour' }}</button>
        }
        @if (status()) { <span class="text-sm text-muted">{{ status() }}</span> }
      </div>
    </section>

    <section class="panel">
      <h2 class="mb-2.5 text-base font-bold">Dépendances</h2>
      <ul>
        @for (c of credits; track c.name) {
          <li class="flex items-center gap-2.5 border-t border-line py-2">
            <div class="min-w-0 flex-1"><strong>{{ c.name }}</strong><small class="block text-muted">@if (c.version) { {{ c.version }} · }{{ c.license }}</small></div>
            <a class="icon-btn" [href]="c.url" target="_blank" rel="noopener" [attr.aria-label]="'Site web de ' + c.name">{{ ui.external }}</a>
          </li>
        }
      </ul>
    </section>
  `,
})
export class AboutPage {
  protected readonly updates = inject(UpdateService);
  protected readonly version = APP_VERSION;
  protected readonly credits = CREDITS;
  protected readonly ui = UI_ICONS;
  protected readonly checking = signal(false);
  protected readonly status = signal('');

  protected async check(): Promise<void> {
    this.checking.set(true);
    this.status.set('');
    try {
      const result = await this.updates.check();
      this.status.set(result === 'ready' ? 'Nouvelle version prête.' : result === 'none' ? 'Application à jour.' : 'Mises à jour indisponibles (mode développement ou navigateur non compatible).');
    } catch {
      this.status.set(navigator.onLine ? 'Vérification impossible.' : 'Hors ligne.');
    } finally {
      this.checking.set(false);
    }
  }
}
